pragma solidity ^0.6.5;

library LibSafeMathRichErrorsV06 {
  // bytes4(keccak256("Uint256BinOpError(uint8,uint256,uint256)"))
  bytes4 internal constant UINT256_BINOP_ERROR_SELECTOR = 0xe946c1bb;

  // bytes4(keccak256("Uint256DowncastError(uint8,uint256)"))
  bytes4 internal constant UINT256_DOWNCAST_ERROR_SELECTOR = 0xc996af7b;

  enum BinOpErrorCodes {
    ADDITION_OVERFLOW,
    MULTIPLICATION_OVERFLOW,
    SUBTRACTION_UNDERFLOW,
    DIVISION_BY_ZERO
  }

  enum DowncastErrorCodes {
    VALUE_TOO_LARGE_TO_DOWNCAST_TO_UINT32,
    VALUE_TOO_LARGE_TO_DOWNCAST_TO_UINT64,
    VALUE_TOO_LARGE_TO_DOWNCAST_TO_UINT96,
    VALUE_TOO_LARGE_TO_DOWNCAST_TO_UINT128
  }

  // solhint-disable func-name-mixedcase
  function Uint256BinOpError(
    BinOpErrorCodes errorCode,
    uint256 a,
    uint256 b
  ) internal pure returns (bytes memory) {
    return
      abi.encodeWithSelector(UINT256_BINOP_ERROR_SELECTOR, errorCode, a, b);
  }

  function Uint256DowncastError(DowncastErrorCodes errorCode, uint256 a)
    internal
    pure
    returns (bytes memory)
  {
    return
      abi.encodeWithSelector(UINT256_DOWNCAST_ERROR_SELECTOR, errorCode, a);
  }
}

